const {chromium}=require('./browser/node_modules/playwright');const fs=require('fs');
(async()=>{const browser=await chromium.launch({headless:true});const ctx=await browser.newContext({viewport:{width:1440,height:1000}});const page=await ctx.newPage();const errors=[];page.on('pageerror',e=>errors.push(e.message));page.on('response',r=>{if(r.status()>=500)errors.push(r.status()+' '+r.url())});
await page.goto('http://127.0.0.1:4181/ro/');await page.waitForSelector('.hero');await page.locator('[data-action=cookies]').click();await page.screenshot({path:'outputs/dracula-design-office/preview-desktop.png',fullPage:true});console.log('HOME',await page.locator('.product').count(),'products');
await page.locator('.product-image').first().click();await page.locator('[data-action=add]').first().click();await page.waitForTimeout(500);console.log('BAG',await page.locator('.bag-count').textContent());
await page.goto('http://127.0.0.1:4181/ro/account');await page.locator('[data-action=auth][data-mode=register]').click();const email='dracula-test-'+Date.now()+'@example.com';await page.locator('[name=full_name]').fill('Preview Test');await page.locator('[name=email]').fill(email);await page.locator('[name=password]').fill('PreviewTest-2026!');await page.locator('[name=password_confirm]').fill('PreviewTest-2026!');await page.locator('[name=accept_terms]').check();await page.locator('form button[type=submit]').click();await page.waitForTimeout(700);console.log('REGISTER',await page.locator('.form-error').allTextContents(),await page.locator('h1').textContent());
if(await page.locator('[data-action=logout]').count()){
await page.goto('http://127.0.0.1:4181/ro/collection');await page.locator('[data-action=favorite]').first().click();await page.waitForTimeout(400);console.log('FAVORITE',await page.locator('[data-action=favorite]').first().getAttribute('aria-pressed'));
await page.goto('http://127.0.0.1:4181/ro/checkout');await page.waitForSelector('[name=first_name]');for(const [key,val] of Object.entries({first_name:'Preview',last_name:'Test',phone:'0722123456',line1:'Strada Test 1',city:'Brasov',county:'Brasov',postal_code:'500001'}))await page.locator('[name='+key+']').fill(val);await page.locator('[name=accept_terms]').check();await page.screenshot({path:'outputs/dracula-design-office/preview-checkout.png',fullPage:true});await page.locator('form button[type=submit]').click();await page.waitForTimeout(600);console.log('CHECKOUT',await page.locator('.form-error').allTextContents(),await page.locator('h1').textContent());
}
await page.goto('http://127.0.0.1:4181/de/');await page.waitForSelector('.hero');console.log('DE',await page.locator('h1').textContent());await page.setViewportSize({width:390,height:844});await page.screenshot({path:'outputs/dracula-design-office/preview-mobile.png',fullPage:true});console.log('MOBILE',await page.evaluate(()=>({width:innerWidth,scroll:document.documentElement.scrollWidth})));
await page.goto('http://127.0.0.1:4181/admin/');await page.waitForTimeout(1200);console.log('ADMIN',await page.title(),await page.locator('h1').allTextContents());console.log('ERRORS',errors);await browser.close();})();

